  "ctl.ja_existe": { pt: "já existe {nome}", en: "{nome} already exists" },
  "ctl.modulo_criado": { pt: "{arq}: um módulo — no controle.py, import {mod} e chame {mod}.passo(…) onde ele entra no fluxo", en: "{arq}: a module — in controle.py, import {mod} and call {mod}.passo(…) where it enters the flow" },
  "ctl.novo_arq_c_html": { pt: "Um <b>módulo em C</b>: o par <code>nome.h</code> (o que ele oferece: as declarações das funções) e <code>nome.c</code> (o código), como se organiza um firmware. O controle.c faz <code>#include \"nome.h\"</code> e chama as funções na mesma amostra, sem atraso.", en: "A <b>C module</b>: the pair <code>name.h</code> (what it offers: the function declarations) and <code>name.c</code> (the code), the way firmware is organized. controle.c does <code>#include \"name.h\"</code> and calls the functions in the same sample, with no delay." },
